<script setup lang="ts">import {ref,onMounted} from 'vue';import {request} from '../api/client';import type {Audit} from '../types/domain';import {useTask} from '../hooks/useTask';import {date} from '../utils/format';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const rows=ref<Audit[]>([]),{error,perform}=useTask();async function load(){rows.value=await request<Audit[]>('/audit');}onMounted(()=>perform(load));</script><template><PageTitle index="06" title="让每次判断都有可查的来路" text="保留最近100次研究写入、资格批准与导出请求，包括被拒绝的权限操作。"><button class="outline" @click="perform(load)">刷新留痕 ↻</button></PageTitle><ErrorNotice :message="error" @retry="perform(load)"/><div class="table-wrap"><table><thead><tr><th>记录时间</th><th>团队账号</th><th>动作</th><th>请求结果</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{date(r.created_at)}}</td><td>{{r.actor}}</td><td><code>{{r.action}}</code></td><td :class="r.status_code<400?'green':'plum'">{{r.status_code}}</td></tr></tbody></table></div></template>
